import { expect, test, uniqueName } from "../../fixtures";

const TAG = "@REV-06";

type Json = Record<string, any>;

async function waitFor<T>(
  check: () => Promise<T | undefined>,
  label: string,
  timeoutMs = 60_000,
): Promise<T> {
  const deadline = Date.now() + timeoutMs;
  while (Date.now() < deadline) {
    const value = await check();
    if (value !== undefined) return value;
    await new Promise((resolve) => setTimeout(resolve, 500));
  }
  throw new Error(`timed out waiting for ${label}`);
}

test.describe("review vendors", () => {
  test(
    "rejecting an extraction requires a note and returns the vendor to the member",
    { tag: TAG },
    async ({ apiAs }) => {
      // Arrange: a member creates a vendor and uploads the three documents.
      const member = await apiAs("member");
      const reviewer = await apiAs("reviewer");
      const name = uniqueName("Review Rejects");

      const created = await member.post("/api/vendors", {
        data: {
          name,
          category: "services",
          contact_email: `ops+${Date.now().toString(36)}${Math.random().toString(36).slice(2, 6)}@example.test`,
        },
      });
      expect(created.status()).toBe(201);
      const vendor = (await created.json()) as Json;
      const vendorId: string = vendor.id;

      const kinds = ["w9", "insurance_certificate", "contract"] as const;
      const documentIds: Record<string, string> = {};
      for (const kind of kinds) {
        const upload = await member.post(`/api/vendors/${vendorId}/documents`, {
          multipart: {
            kind,
            file: {
              name: `${kind}-${vendorId}.pdf`,
              mimeType: "application/pdf",
              buffer: Buffer.from(`%PDF-1.4 fake ${kind} ${vendorId}`),
            },
          },
        });
        expect(upload.status()).toBe(201);
        documentIds[kind] = ((await upload.json()) as Json).id;
      }

      // Wait until every document has been extracted, then submit.
      for (const kind of kinds) {
        await waitFor(async () => {
          const res = await member.get(`/api/documents/${documentIds[kind]}`);
          expect(res.status()).toBe(200);
          const doc = (await res.json()) as Json;
          return doc.status === "extracted" ? doc : undefined;
        }, `document ${kind} extracted`);
      }

      const submitted = await member.post(`/api/vendors/${vendorId}/submit`);
      expect(submitted.status()).toBe(200);
      expect(((await submitted.json()) as Json).status).toBe("in_review");

      const w9Extraction = (await (
        await reviewer.get(`/api/documents/${documentIds.w9}/extraction`)
      ).json()) as Json;
      expect(w9Extraction.status).toBe("pending_review");
      const extractionId: string = w9Extraction.id;

      // Act: reject without a note.
      const withoutNote = await reviewer.post(`/api/extractions/${extractionId}/decision`, {
        data: { decision: "reject" },
      });

      // Assert: validation failure.
      expect(withoutNote.status()).toBe(422);

      // Act: reject with a note.
      const withNote = await reviewer.post(`/api/extractions/${extractionId}/decision`, {
        data: { decision: "reject", note: "Tax ID does not match" },
      });
      expect(withNote.status()).toBe(200);
      const decided = (await withNote.json()) as Json;
      expect(decided.status).toBe("rejected");
      expect(decided.review_note).toBe("Tax ID does not match");

      // Assert: vendor is rejected and the audit trail records the event.
      const vendorRes = await member.get(`/api/vendors/${vendorId}`);
      expect(vendorRes.status()).toBe(200);
      expect(((await vendorRes.json()) as Json).status).toBe("rejected");

      const auditRes = await reviewer.get(`/api/vendors/${vendorId}/audit`);
      expect(auditRes.status()).toBe(200);
      const items = ((await auditRes.json()) as Json).items as Json[];
      expect(items.map((event) => event.action)).toContain("extraction.rejected");
    },
  );
});
